    crate::testport::assert_eq(oil_word_base(0), 6, "word base only");
    crate::testport::assert_eq(oil_word_base((((oc_wlang() + oc_style()) + oc_psize()) + oc_lexicon()) + oc_walts()), 11, "word groups include the word-alternative count");
